from datetime import date

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

from app.auth import current_customer
from app.db import get_db

router = APIRouter(prefix="/parcels", tags=["parcels"])


class Move(BaseModel):
    pickup_date: date


@router.post("/{parcel_id}/move")
def move_pickup(parcel_id: int, move: Move, customer=Depends(current_customer), db=Depends(get_db)):
    parcel = db.execute("SELECT id, status, pickup_date FROM parcels WHERE id = %s", (parcel_id,)).fetchone()
    if parcel is None:
        raise HTTPException(status_code=404, detail="No parcel with that id")
    if move.pickup_date <= date.today():
        raise HTTPException(status_code=422, detail="Choose a day after today")
    db.execute("UPDATE parcels SET pickup_date = %s WHERE id = %s", (move.pickup_date, parcel_id))
    return {"id": parcel_id, "pickup_date": move.pickup_date.isoformat()}

