from fastapi.testclient import TestClient

from app.auth import current_customer
from app.db import get_db
from app.main import app


class FakeDb:
    def __init__(self, row):
        self.row = row

    def execute(self, query, params=None):
        return self

    def fetchone(self):
        return self.row


def test_moves_a_pickup_to_a_later_day():
    app.dependency_overrides[current_customer] = lambda: {"id": 1, "email": "ada@example.com", "name": "Ada"}
    app.dependency_overrides[get_db] = lambda: FakeDb({"id": 7, "status": "booked", "pickup_date": "2026-10-12"})
    client = TestClient(app)
    response = client.post("/parcels/7/move", json={"pickup_date": "2099-01-15"}, headers={"Authorization": "Bearer t"})
    assert response.status_code == 200
    assert response.json()["pickup_date"] == "2099-01-15"
